#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Verify HTML docs generated by md2html.py — checklist chất lượng của skill.

Usage:  python3 verify.py [docs_dir]     # default: ./docs
Exit 0 = clean, exit 1 = có lỗi (in ra list).

Kiểm tra: fence còn sót, token chưa thay, escape đôi, bảng wrap đôi,
blockquote chưa chuyển callout, link hỏng. In stats quy mô.
"""
import re
import sys
from pathlib import Path

root = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path("docs").resolve()

CHECKS = [
    ("```", "fence chưa xử lý"),
    ("@@BLOCK", "token chưa thay"),
    ("amp;amp;", "escape đôi"),
    ('tablewrap"><div class="tablewrap">', "bảng bị wrap đôi"),
    ("<blockquote>", "blockquote chưa chuyển callout"),
]

problems = []
stats = {"codeblock": 0, "callout": 0, "tablewrap": 0, "toc": 0, "copybtn": 0, "mermaid": 0}
files = sorted(root.rglob("*.html"))

for f in files:
    t = f.read_text(encoding="utf-8")
    for pat, msg in CHECKS:
        if pat in t:
            problems.append(f"{f.relative_to(root)}: {msg}")
    stats["codeblock"] += t.count('<div class="codeblock">')
    stats["callout"] += t.count('<div class="callout ')
    stats["tablewrap"] += t.count('<div class="tablewrap">')
    stats["toc"] += t.count('<aside class="toc"')
    stats["copybtn"] += t.count('class="copybtn"')
    stats["mermaid"] += t.count('<div class="mermaid">')
    # wiki-link không được lọt vào trong sơ đồ mermaid (phá vỡ cú pháp)
    for mdiv in re.finditer(r'<div class="mermaid">(.*?)</div>', t, re.S):
        if "<a " in mdiv.group(1):
            problems.append(f"{f.relative_to(root)}: wiki-link leaked vào mermaid")
    for href in re.findall(r'href="([^"]+\.html)(?:#[^"]*)?"', t):
        if not (f.parent / href.split("#")[0]).resolve().exists():
            problems.append(f"{f.relative_to(root)}: link hỏng -> {href}")

print(f"Scanned {len(files)} HTML files under {root}")
print(f"stats: {stats}")
if problems:
    print(f"\n❌ {len(problems)} problems:")
    for p in problems:
        print(f"  - {p}")
    sys.exit(1)
print("\nALL CLEAN ✓")